def all_exercises():
    result={1:list(EXERCISES)}
    for n,items in PROMPTS.items():
        rows=[]
        for j,(topic,q) in enumerate(items):
            kind='conceptual' if j<5 else 'scenario';ident=('C'+str(j+1)) if j<5 else 'S'+str(j-4)
            answer=LESSONS[n][topic-1]['prose']
            rows.append((kind,ident,q,answer))
        task,explanation=TASKS[n]
        rows.append(('design','D1','Design or debug the running system: '+task,explanation+' Begin with the smallest correct boundary and identify an observable failure of the naive alternative.'))
        rows.append(('implementation','I1',task+' Include a counterexample and a corrected result.',explanation))
        answer='A defensible answer must state the changed contract, the authoritative owner, and the failure history before choosing a mechanism. '+LESSONS[n][-1]['prose']+' A component name or a claim that more replicas solve it is insufficient; show how the proposed history remains valid under the stated failure.'
        rows.append(('thought_experiment','T1',THOUGHT[n],answer))
        result[n]=rows
    c=CASES
    result[22]=[
      ('conceptual','C1','Why do the twelve designs use different authoritative and derived state boundaries?',c[1]['sections'][13]+' '+c[5]['sections'][13]),
      ('conceptual','C2','Why are a chat persistence receipt and a human read receipt different?',c[3]['sections'][0]+' '+c[3]['sections'][13]),
      ('conceptual','C3','Why can a scheduler lease not guarantee a single external execution?',c[10]['sections'][13]),
      ('conceptual','C4','Why does a collaborative editor need more than eventual string equality?',c[11]['sections'][13]+' '+c[11]['sections'][14]),
      ('conceptual','C5','Why is a document-processing complete state inadequate without provenance and publication evidence?',c[12]['sections'][11]+' '+c[12]['sections'][16]),
      ('scenario','S1','A booking payment succeeds after its seat hold expires. What outcomes are safe?',c[8]['sections'][8]+' '+c[8]['sections'][11]),
      ('scenario','S2','A payment provider charges, the local process dies, and a client retries. What prevents a second logical charge?',c[9]['sections'][8]+' '+c[9]['sections'][13]),
      ('scenario','S3','A deleted document has an old extraction worker still running. What must prevent publication?',c[12]['sections'][8]+' '+c[12]['sections'][13]),
      ('design','D1','Review the URL shortener at 100000 redirects/s with a cold cache and immediate revocation requirement.',c[1]['sections'][9]+' '+c[1]['sections'][11]+' '+c[1]['sections'][20]),
      ('implementation','I1','Choose one case and implement its final challenge with failure injection and an explicit invariant.','Each case ends with a specific miniature implementation challenge. Use stable identities, test the stated failure window, and compare the result with the case invariant. For the included examples, run verify_mechanisms.py and inspect the outbox and ledger fixtures. A success-only demonstration is insufficient because it does not exercise the proposed recovery boundary.'),
      ('thought_experiment','T1','You may fund only one improvement in a small platform: another region, tested restores, or stronger retry and reconciliation. How do you decide?','There is no universal winner. Start from the most harmful demonstrated or unacceptable failure and the original requirements. Another region cannot repair a lost idempotency history, and retries cannot restore a destroyed sole copy. Tested restores establish only their tested recovery scope. Compare risk reduction, cost, staffing, and the evidence each choice would produce; record the decision and revisit trigger.')]
    return result
